private static boolean getMutedFromManager(AudioManager audioManager,@C.StreamType int streamType){
  try {
    if (Util.SDK_INT >= 23) {
      return audioManager.isStreamMute(streamType);
    }
    else {
      return audioManager.getStreamVolume(streamType) == 0;
    }
  } catch (IllegalArgumentException e) {
    return false;
  }
}
